#include <stdio.h>

int main(void) {
    int bowls[8];
    int n;

    if (scanf("%d", &n) != 1) {
        return 1;
    }
    for (int i = 0; i < n; i++) {
        if (scanf("%d", &bowls[i]) != 1) {
            return 1;
        }
    }

    int *best = bowls;
    for (int *q = bowls; q < bowls + n; q++) {
        if (*q > *best) {
            best = q;
        }
    }

    printf("最多的是第 %d 只，%d 条\n", (int)(best - bowls), *best);
    return 0;
}
